"use client";
import { ArtemisScope } from "./artemis-scope";
import View2 from "./components/image-galleries/variants/03-focus-rail";
const variants = {"focus-rail":View2};
export interface ArtemisImageGalleriesProps { className?: string; variant?: "focus-rail"; }
export function ArtemisImageGalleries({ className, variant = "focus-rail" }: ArtemisImageGalleriesProps) {const View = variants[variant];return <ArtemisScope className={className}><div className="art:flex art:w-full art:min-w-0 art:flex-col art:items-center"><View/></div></ArtemisScope>;}

"use client";
// @zeus-internal
import { useEffect, useRef, useState } from "react";
import { motion, useInView, useReducedMotion } from "motion/react";
import { artemisButtonClasses } from "../../../foundations/button-classes";
import { ARTEMIS_SPRING_LAYOUT } from "../../../lib/ease";
import { useArtemisReduceAfterHydration } from "../../../lib/use-reduce-after-hydration";
import { RAIL_ITEMS } from "./03-focus-rail/items";
export default function ImageGalleriesFocusRail() {
    const [active, setActive] = useState(0);
    const sectionRef = useRef<HTMLElement>(null);
    const visible = useInView(sectionRef, { margin: "120px" });
    const reduced = useReducedMotion() ?? false;
    const staticReduced = useArtemisReduceAfterHydration();
    useEffect(() => {
        if (!visible || reduced)
            return;
        const timer = window.setInterval(() => setActive((current) => (current + 1) % RAIL_ITEMS.length), 4200);
        return () => window.clearInterval(timer);
    }, [visible, reduced]);
    return (<section ref={sectionRef} className="art:w-full art:overflow-hidden art:bg-background art:px-4 art:py-20 art:text-foreground art:@min-[640px]/artemis:px-8 art:@min-[640px]/artemis:py-24">
      <div className="art:mx-auto art:w-full art:max-w-7xl">
          <header className="art:grid art:gap-6 art:pb-9 art:@min-[768px]/artemis:grid-cols-[1.2fr_0.8fr] art:@min-[768px]/artemis:items-end art:@min-[768px]/artemis:gap-16">
            <div>
              <p className="art:font-medium art:text-muted-foreground art:text-xs art:uppercase art:tracking-[0.16em]">
                {"Spaces in focus"}
              </p>
              <h2 className="art:mt-5 art:max-w-3xl art:text-balance art:font-medium art:text-4xl art:leading-[1.02] art:tracking-[-0.045em]">
                <span className="art:block">
                  {"Move through images"}
                </span>
                <span className="art:block">
                  {"one frame at a time"}
                </span>
              </h2>
            </div>
            <div className="art:@min-[768px]/artemis:justify-self-end">
              <p className="art:max-w-md art:text-pretty art:text-muted-foreground art:leading-7">
                {"Select a frame or let the gallery quietly move the focus for you"}
              </p>
              <p className="art:mt-5 art:font-mono art:text-muted-foreground art:text-xs art:tabular-nums art:tracking-[0.12em]">
                {String(active + 1).padStart(2, "0")}
                {" /"}
                {" "}
                {"06"}
              </p>
            </div>
          </header>
        <div className="art:flex art:h-[38rem] art:flex-col art:gap-2 art:border-border art:border-y art:py-2 art:@min-[768px]/artemis:h-[35rem] art:@min-[768px]/artemis:flex-row">
          {RAIL_ITEMS.map((item, index) => {
            const selected = index === active;
            return (<motion.div key={item.title} className="art:group art:relative art:min-h-0 art:min-w-0 art:basis-0 art:overflow-hidden art:bg-muted art:has-[:focus-visible]:ring-2 art:has-[:focus-visible]:ring-ring art:has-[:focus-visible]:ring-offset-2 art:has-[:focus-visible]:ring-offset-background" style={{ borderRadius: 24, ...(staticReduced ? { flexGrow: selected ? 4.4 : 1 } : {}) }} animate={staticReduced ? undefined : { flexGrow: selected ? 4.4 : 1 }} transition={reduced ? { duration: 0 } : ARTEMIS_SPRING_LAYOUT}>
                <motion.img src={item.src} alt={item.alt} width={1200} height={1600} loading="lazy" className="art:h-full art:w-full art:object-cover" animate={{ scale: reduced || selected ? 1 : 1.045 }} transition={reduced ? { duration: 0 } : ARTEMIS_SPRING_LAYOUT}/>
                {selected && (<motion.span className="art:absolute art:right-3 art:bottom-3 art:left-3 art:flex art:items-end art:justify-between art:gap-4 art:rounded-2xl art:bg-background/80 art:p-4 art:text-foreground art:backdrop-blur-md" initial={reduced ? false : { opacity: 0, y: 10, filter: "blur(6px)" }} animate={{ opacity: 1, y: 0, filter: "blur(0px)" }} transition={reduced ? { duration: 0 } : { duration: 0.4, delay: 0.12, ease: "easeOut" }}>
                    <span className="art:font-medium art:text-sm">{item.title}</span>
                    <span className="art:text-muted-foreground art:text-xs">{item.caption}</span>
                  </motion.span>)}
                <button type="button" className={artemisButtonClasses({ variant: "link", size: "none", className: "art:inline-block art:p-0 art:font-normal art:text-inherit art:hover:bg-transparent art:hover:text-inherit art:absolute art:inset-0 art:size-full art:cursor-pointer art:outline-none art:focus-visible:ring-0 art:focus-visible:ring-offset-0" })} aria-label={`Show ${item.title}`} aria-pressed={selected} onClick={() => setActive(index)}/>
              </motion.div>);
        })}
        </div>
      </div>
    </section>);
}

// @zeus-internal
export const RAIL_ITEMS = [
    {
        title: "Coastal house",
        caption: "Morning light",
        src: "/assets/artemis/00f08a1b00c26bee6c90.avif",
        alt: "Sunlit living room overlooking the coast",
    },
    {
        title: "Stone study",
        caption: "Material archive",
        src: "/assets/artemis/2ce5b4a2815dab6dd072.avif",
        alt: "Sculptural stone interior detail",
    },
    {
        title: "The long room",
        caption: "Working studio",
        src: "/assets/artemis/0fa3094a5a49b43eda46.avif",
        alt: "Quiet creative studio with long worktables",
    },
    {
        title: "Inner court",
        caption: "Late afternoon",
        src: "/assets/artemis/e9310d36bf6a9fb11295.avif",
        alt: "Warm modern courtyard framed by timber",
    },
    {
        title: "White gallery",
        caption: "Natural light",
        src: "/assets/artemis/d2a1ef4851ad61ca357c.avif",
        alt: "Minimal gallery room washed in natural light",
    },
    {
        title: "Linen room",
        caption: "Quiet collection",
        src: "/assets/artemis/c9aef230b242a95490ed.avif",
        alt: "Calm bedroom layered with natural linen",
    },
] as const;
